export class AppError extends Error {
  readonly status: number;
  readonly title: string;
  readonly type: string;
  readonly extra: Record<string, unknown>;

  constructor(status: number, title: string, detail: string, options: AppErrorOptions = {}) {
    super(detail, { cause: options.cause });
    this.name = new.target.name;
    this.status = status;
    this.title = title;
    this.type = options.type === undefined ? "about:blank" : `${PROBLEM_BASE}${options.type}`;
    this.extra = options.extra ?? {};
  }
}

/** 400: the request itself is malformed. `errors` names each field and what is wrong with it. */
export class ValidationError extends AppError {
  readonly errors: FieldError[];

  constructor(errors: FieldError[], detail = "The request has invalid fields") {
    super(400, "Bad Request", detail, { extra: { errors } });
    this.errors = errors;
  }
}
// ...
/** 404: also used for things the caller may not know exist, so a 403 does not reveal them. */
export class NotFoundError extends AppError {
  constructor(detail: string) {
    super(404, "Not Found", detail);
  }
}

/** Maps any thrown value to a problem. Pure, so it is easy to test. */
export function toProblem(err: unknown): Problem {
  if (err instanceof AppError) {
    const problem: Problem = { type: err.type, title: err.title, status: err.status, ...err.extra };
    return err.message === "" ? problem : { ...problem, detail: err.message };
  }
  if (err instanceof ZodError) {
    return { ...plain(400, "Bad Request", "The request has invalid fields"), errors: toFieldErrors(err, "body") };
  }
  // ...
  return plain(500, "Internal Server Error");
}
// ...
export const errorHandler: ErrorRequestHandler = (err, req, res, next) => {
  if (res.headersSent) {
    // Too late for a problem response: let Express close the connection.
    req.log.warn({ err }, "error after the response started");
    next(err);
    return;
  }
  const problem = toProblem(err);
  // 503s are expected while a dependency is down or during shutdown: a warning, not an error.
  if (problem.status === 503) req.log.warn({ err }, "service unavailable");
  else if (problem.status >= 500) req.log.error({ err }, "request failed");

  if (err instanceof UnauthorizedError) res.set("WWW-Authenticate", err.challenge);
  // The request id travels in the X-Request-Id header, so two answers to the same mistake are
  // byte-identical (a login must not differ between "no such user" and "wrong password").
  res.status(problem.status).type("application/problem+json").json({ ...problem, instance: req.originalUrl });
};

/** 401 unless the request carries a valid access token. */
export function requireAuth(tokens: AccessTokenVerifier): RequestHandler {
  return async (req, _res, next) => {
    const token = bearerToken(req.get("authorization"));
    if (token === undefined) throw new UnauthorizedError("Send an access token: Authorization: Bearer <token>");
    if (token === null) throw new UnauthorizedError("Malformed Authorization header", { invalidToken: true });
    req.user = await tokens.verifyAccessToken(token);
    next();
  };
}
// ...
/** 403 unless the logged-in user has one of the roles. Goes after requireAuth. */
export function requireRole(...allowed: Role[]): RequestHandler {
  return (req, _res, next) => {
    if (req.user === undefined) throw new UnauthorizedError();
    if (!allowed.includes(req.user.role)) {
      throw new ForbiddenError(`Only ${allowed.join(" or ")} accounts can do this`);
    }
    next();
  };
}

/** Published and cancelled events are public. A draft is visible only to its organizer and admins. */
export function canViewEvent(user: AuthUser | null | undefined, event: EventOwnership): boolean {
  if (event.status !== "draft") return true;
  return user != null && (user.role === "admin" || user.id === event.organizerId);
}

/** Only the organizer who owns the event, or an admin, may change it or its ticket types. */
export function canEditEvent(user: AuthUser, event: EventOwnership): boolean {
  return user.role === "admin" || (user.role === "organizer" && user.id === event.organizerId);
}

